def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    v4 = vars["v4"]

    total_2010 = v1 + v2
    total_2009 = v3 + v4
    total = total_2010 + total_2009

    return {
        "value": total,
        "trace": {
            "total_2010": total_2010,
            "total_2009": total_2009,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
